        '{"randomize_questions":false,"randomize_options":false,"assessment_kind":"formative","grade_level":"10","curriculum":"MYP 5","subject":"Mathematics","duration_minutes":45,"total_marks":50,"source":"assess-prep-myp5-formative"}'::jsonb, '3c3ed712-f409-4aa1-a645-816418e22ec4')
