select ('b5000000-0000-4000-8000' || lpad((100 + (x->>'n')::int)::text, 12, '0'))::uuid,
       '0a400000-0000-4000-8000-000000000001', x->>'t', x->>'p', x->'d', x->>'e', null,
       (x->>'m')::numeric, x->>'df', x->>'tp', x->>'st',
       array['MYP 5', 'Mathematics', 'formative', 'assess-prep'], 'published', x->'cfg', '3c3ed712-f409-4aa1-a645-816418e22ec4',
       'MYP', 'MYP 5 Mathematics', '0a400000-0000-4000-8000-000000000030', 'approved', 'manual', '0a400000-0000-4000-8000-000000000110'
  from jsonb_array_elements('[{"n":1,"t":"assess_parts","p":"A sequence is defined recursively by $a_1 = 5$ and $a_n = a_{n-1} + 4$.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A sequence is defined recursively by "},{"type":"mathInline","attrs":{"latex":"a_1 = 5"}},{"type":"text","text":" and "},{"type":"mathInline","attrs":{"latex":"a_n = a_{n-1} + 4"}},{"type":"text","text":"."}]}]},"e":"Start at 5 and add 4 each time: 5, 9, 13, 17, 21. So the 3rd term is 13 and the 5th term is 21.\n\nHint for next time: A recursive rule builds each term from the one before it.","m":2,"df":"easy","tp":"explicit and recursive formulas","st":"generating terms from a recursive rule","cfg":{"source":"assess-prep-myp5-formative","question_number":1,"myp_criterion":"B","next_time_hint":"A recursive rule builds each term from the one before it.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the 3rd term.","kind":"numeric","points":1,"hints":["A recursive rule builds each term from the one before it.","Start with a₁ = 5 and apply the rule step by step."],"answer":13,"tolerance":0},{"id":"b","label":"(b)","prompt":"Find the 5th term.","kind":"numeric","points":1,"hints":["Keep applying the same rule — do not restart from a₁ each time.","Continue the chain from your 3rd term."],"answer":21,"tolerance":0}]}},{"n":2,"t":"assess_parts","p":"A sequence begins 7, 11, 15, 19, …","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A sequence begins 7, 11, 15, 19, …"}]}]},"e":"The terms increase by 4 each time. The explicit formula is aₙ = 7 + (n − 1) × 4 = 4n + 3. Check: n = 1 gives 7.\n\nHint for next time: Compare neighbouring terms.","m":2,"df":"easy","tp":"explicit and recursive formulas","st":"from a list to an explicit formula","cfg":{"source":"assess-prep-myp5-formative","question_number":2,"myp_criterion":"B","next_time_hint":"Compare neighbouring terms.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"What is the common difference?","kind":"numeric","points":1,"hints":["Compare neighbouring terms.","Subtract each term from the next one."],"answer":4,"tolerance":0},{"id":"b","label":"(b)","prompt":"Write the explicit formula for the nth term. Type it like 4n+3.","kind":"expression","points":1,"hints":["An explicit formula uses n directly — it does not need the previous term.","Use the pattern ''first term + (n − 1) × difference'' and simplify."],"accepted":["4n+3","a_n=4n+3","an=4n+3","3+4n","7+4(n-1)","4n + 3"]}]}},{"n":3,"t":"assess_parts","p":"The diagrams show matchstick squares in a row: Pattern 1 uses 4 matches, Pattern 2 uses 7 and Pattern 3 uses 10.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The diagrams show matchstick squares in a row: Pattern 1 uses 4 matches, Pattern 2 uses 7 and Pattern 3 uses 10."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"shape_pattern","title":"Matchstick squares","patterns":[{"label":"Pattern 1","squares":1},{"label":"Pattern 2","squares":2},{"label":"Pattern 3","squares":3}]}}}]},"e":"Each new square shares a side, adding 3 matches: 4, 7, 10, 13, … Pattern 4 uses 13. The explicit formula is aₙ = 4 + (n − 1) × 3 = 3n + 1.\n\nHint for next time: Look at how the count grows from one pattern to the next.","m":2,"df":"medium","tp":"explicit and recursive formulas","st":"shape patterns and explicit formulas","cfg":{"source":"assess-prep-myp5-formative","question_number":3,"myp_criterion":"B","next_time_hint":"Look at how the count grows from one pattern to the next.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many matches does Pattern 4 use?","kind":"numeric","points":1,"hints":["Look at how the count grows from one pattern to the next.","Find the increase between patterns, then continue the sequence."],"answer":13,"tolerance":0},{"id":"b","label":"(b)","prompt":"Write an explicit formula for the number of matches in Pattern n. Type it like 3n+1.","kind":"expression","points":1,"hints":["Connect the pattern number n to the count, not the previous pattern.","Use ''starting value + (n − 1) × increase'' and simplify, then check n = 1."],"accepted":["3n+1","a_n=3n+1","an=3n+1","1+3n","4+3(n-1)"]}]}},{"n":4,"t":"assess_parts","p":"Spot the mistake. For $a_1 = 4$ and $a_n = 2a_{n-1} - 1$, a student writes: $a_2 = 2(4) - 1 = 7$, then $a_3 = 2(4) - 1 = 7$, then $a_4 = 2(4) - 1 = 7$.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Spot the mistake. For "},{"type":"mathInline","attrs":{"latex":"a_1 = 4"}},{"type":"text","text":" and "},{"type":"mathInline","attrs":{"latex":"a_n = 2a_{n-1} - 1"}},{"type":"text","text":", a student writes: "},{"type":"mathInline","attrs":{"latex":"a_2 = 2(4) - 1 = 7"}},{"type":"text","text":", then "},{"type":"mathInline","attrs":{"latex":"a_3 = 2(4) - 1 = 7"}},{"type":"text","text":", then "},{"type":"mathInline","attrs":{"latex":"a_4 = 2(4) - 1 = 7"}},{"type":"text","text":"."}]}]},"e":"The student keeps substituting the FIRST term (4) instead of the PREVIOUS term. Correctly: a₂ = 7, a₃ = 2(7) − 1 = 13, a₄ = 2(13) − 1 = 25.\n\nHint for next time: In a recursive rule, ''previous term'' changes at every step.","m":2,"df":"medium","tp":"explicit and recursive formulas","st":"spot the mistake: recursive rules","cfg":{"source":"assess-prep-myp5-formative","question_number":4,"myp_criterion":"C","next_time_hint":"In a recursive rule, ''previous term'' changes at every step.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the correct value of $a_3$.","kind":"numeric","points":1,"hints":["In a recursive rule, ''previous term'' changes at every step.","Apply the rule to a₂, not to a₁."],"answer":13,"tolerance":0},{"id":"b","label":"(b)","prompt":"Find the correct value of $a_4$.","kind":"numeric","points":1,"hints":["Feed your corrected a₃ back into the same rule.","Double your answer to (a), then subtract 1."],"answer":25,"tolerance":0}]}},{"n":5,"t":"assess_parts","p":"An arithmetic sequence has first term 3 and common difference 6.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An arithmetic sequence has first term 3 and common difference 6."}]}]},"e":"a₁₀ = 3 + (10 − 1) × 6 = 3 + 54 = 57. The explicit formula is aₙ = 3 + (n − 1) × 6 = 6n − 3.\n\nHint for next time: In an arithmetic sequence you add the same amount at each step.","m":2,"df":"easy","tp":"arithmetic sequences","st":"nth term of an arithmetic sequence","cfg":{"source":"assess-prep-myp5-formative","question_number":5,"myp_criterion":"A","next_time_hint":"In an arithmetic sequence you add the same amount at each step.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the 10th term.","kind":"numeric","points":1,"hints":["In an arithmetic sequence you add the same amount at each step.","Use first term + (n − 1) × common difference."],"answer":57,"tolerance":0},{"id":"b","label":"(b)","prompt":"Write the explicit formula. Type it like 6n-3.","kind":"expression","points":1,"hints":["Replace the numbers in ''a + (n − 1)d'' with this sequence''s values.","Simplify the formula and check it gives 3 when n = 1."],"accepted":["6n-3","a_n=6n-3","an=6n-3","3+6(n-1)","-3+6n"]}]}},{"n":6,"t":"assess_parts","p":"In an arithmetic sequence, the 4th term is 17 and the 9th term is 37.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In an arithmetic sequence, the 4th term is 17 and the 9th term is 37."}]}]},"e":"From term 4 to term 9 is 5 steps adding 20, so d = 20 ÷ 5 = 4. Then a = 17 − 3 × 4 = 5. Check: a₉ = 5 + 8 × 4 = 37.\n\nHint for next time: Count how many steps of the difference separate the two given terms.","m":3,"df":"medium","tp":"arithmetic sequences","st":"finding a and d from two terms","cfg":{"source":"assess-prep-myp5-formative","question_number":6,"myp_criterion":"B","next_time_hint":"Count how many steps of the difference separate the two given terms.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the common difference.","kind":"numeric","points":1,"hints":["Count how many steps of the difference separate the two given terms.","Subtract the terms, then divide by the number of steps between them."],"answer":4,"tolerance":0},{"id":"b","label":"(b)","prompt":"Find the first term.","kind":"numeric","points":1,"hints":["Work backwards from a known term using the difference.","From the 4th term, undo three steps of the difference."],"answer":5,"tolerance":0},{"id":"c","label":"(c)","prompt":"Write the explicit formula. Type it like 4n+1.","kind":"expression","points":1,"hints":["You now have both ingredients of an arithmetic sequence.","Use ''first term + (n − 1) × difference'' and simplify."],"accepted":["4n+1","a_n=4n+1","an=4n+1","5+4(n-1)","1+4n"]}]}},{"n":7,"t":"numeric","p":"The arithmetic sequence 5, 9, 13, 17, … continues in the same way. Which term is equal to 101? Type the term number.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The arithmetic sequence 5, 9, 13, 17, … continues in the same way. Which term is equal to 101? Type the term number."}]}]},"e":"aₙ = 4n + 1. Setting 4n + 1 = 101 gives 4n = 100, so n = 25.\n\nHint for next time: Set the nth-term formula equal to the target and solve.","m":1,"df":"medium","tp":"arithmetic sequences","st":"finding the term number","cfg":{"source":"assess-prep-myp5-formative","question_number":7,"myp_criterion":"B","next_time_hint":"Set the nth-term formula equal to the target and solve.","assessment_style":"assess_prep_typed","hints":["Turn the question around: build the nth-term formula first.","Set the explicit formula equal to 101 and solve for n."],"numeric_answer":25,"tolerance":0}},{"n":8,"t":"assess_parts","p":"A taxi charges a fixed fee of $4 plus $1.50 for each kilometre travelled.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A taxi charges a fixed fee of "},{"type":"text","text":"$4 plus $"},{"type":"text","text":"1.50 for each kilometre travelled."}]}]},"e":"The cost after n km is C = 4 + 1.5n dollars (each kilometre adds the same amount, like a common difference). For 12 km: 4 + 1.5 × 12 = 4 + 18 = $22.\n\nHint for next time: One part of the cost never changes; the other grows by the same amount per kilometre.","m":2,"df":"medium","tp":"arithmetic sequences","st":"arithmetic sequences in real life","cfg":{"source":"assess-prep-myp5-formative","question_number":8,"myp_criterion":"D","next_time_hint":"One part of the cost never changes; the other grows by the same amount per kilometre.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Write a formula for the cost C after n kilometres. Type it like 4+1.5n.","kind":"expression","points":1,"hints":["One part of the cost never changes; the other grows by the same amount per kilometre.","Fixed fee first, then ''per-km rate × n''."],"accepted":["4+1.5n","C=4+1.5n","1.5n+4","4+3n/2"]},{"id":"b","label":"(b)","prompt":"What is the cost of a 12 km journey?","kind":"numeric","points":1,"hints":["Substitute the distance into your formula.","Replace n with 12 and calculate."],"answer":22,"tolerance":0,"unit":"$"}]}},{"n":9,"t":"assess_parts","p":"A quadratic sequence begins 3, 8, 15, 24, …","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A quadratic sequence begins 3, 8, 15, 24, …"}]}]},"e":"First differences: 5, 7, 9 — they increase by 2 (the second difference), so the next first difference is 11 and the next term is 24 + 11 = 35.\n\nHint for next time: Work out the gaps between terms first, then the gaps between the gaps.","m":2,"df":"easy","tp":"quadratic sequences","st":"second differences","cfg":{"source":"assess-prep-myp5-formative","question_number":9,"myp_criterion":"B","next_time_hint":"Work out the gaps between terms first, then the gaps between the gaps.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"What is the second difference?","kind":"numeric","points":1,"hints":["Work out the gaps between terms first, then the gaps between the gaps.","List the first differences, then subtract neighbouring ones."],"answer":2,"tolerance":0},{"id":"b","label":"(b)","prompt":"Find the next term.","kind":"numeric","points":1,"hints":["Extend the pattern of first differences by one more step.","Add the second difference to the last first difference, then add on."],"answer":35,"tolerance":0}]}},{"n":10,"t":"short_answer","p":"Find the nth term of the quadratic sequence 2, 6, 12, 20, … Type it like n^2+n.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Find the nth term of the quadratic sequence 2, 6, 12, 20, … Type it like n^2+n."}]}]},"e":"First differences 4, 6, 8; second difference 2, so the n² coefficient is 1. Subtracting n² (1, 4, 9, 16) from the terms leaves 1, 2, 3, 4, which is n. So aₙ = n² + n.\n\nHint for next time: Halve the second difference for the n² coefficient, then subtract and look again.","m":1,"df":"medium","tp":"quadratic sequences","st":"nth term of a quadratic sequence","cfg":{"source":"assess-prep-myp5-formative","question_number":10,"myp_criterion":"B","next_time_hint":"Halve the second difference for the n² coefficient, then subtract and look again.","assessment_style":"assess_prep_typed","hints":["A constant second difference tells you the power of n and its coefficient.","Subtract n² from each term and see what pattern is left."],"accepted":["n^2+n","n²+n","a_n=n^2+n","n(n+1)","n+n^2"],"normalize_expression":true}},{"n":11,"t":"assess_parts","p":"A quadratic sequence begins 5, 12, 23, 38, …","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A quadratic sequence begins 5, 12, 23, 38, …"}]}]},"e":"First differences 7, 11, 15; second difference 4, so the next first difference is 19 and the next term is 57. The n² coefficient is 4 ÷ 2 = 2; subtracting 2n² (2, 8, 18, 32) leaves 3, 4, 5, 6 = n + 2, so aₙ = 2n² + n + 2.\n\nHint for next time: Extend the first differences using the second difference.","m":2,"df":"hard","tp":"quadratic sequences","st":"quadratic nth term from differences","cfg":{"source":"assess-prep-myp5-formative","question_number":11,"myp_criterion":"B","next_time_hint":"Extend the first differences using the second difference.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the next term.","kind":"numeric","points":1,"hints":["Extend the first differences using the second difference.","Add the second difference to the last first difference, then add on to the last term."],"answer":57,"tolerance":0},{"id":"b","label":"(b)","prompt":"Write the nth-term formula. Type it like 2n^2+n+2.","kind":"expression","points":1,"hints":["The second difference, halved, gives the n² coefficient.","Subtract 2n² from each term and find the pattern that remains."],"accepted":["2n^2+n+2","2n²+n+2","a_n=2n^2+n+2"]}]}},{"n":12,"t":"assess_parts","p":"A quadratic sequence has nth term $a_n = 3n^2 - 2n + 1$.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A quadratic sequence has nth term "},{"type":"mathInline","attrs":{"latex":"a_n = 3n^2 - 2n + 1"}},{"type":"text","text":"."}]}]},"e":"a₅ = 3(25) − 2(5) + 1 = 75 − 10 + 1 = 66. For the term 281: 3n² − 2n + 1 = 281 → 3n² − 2n − 280 = 0 → (3n + 28)(n − 10) = 0, so n = 10 (term numbers are positive).\n\nHint for next time: An explicit formula works directly from n.","m":2,"df":"hard","tp":"quadratic sequences","st":"using a quadratic formula backwards","cfg":{"source":"assess-prep-myp5-formative","question_number":12,"myp_criterion":"B","next_time_hint":"An explicit formula works directly from n.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the 5th term.","kind":"numeric","points":1,"hints":["An explicit formula works directly from n.","Substitute n = 5 into the formula, squaring before multiplying."],"answer":66,"tolerance":0},{"id":"b","label":"(b)","prompt":"One term of the sequence is 281. Which term is it? Type the term number.","kind":"numeric","points":1,"hints":["Set the formula equal to 281 and solve — expect a quadratic equation.","Rearrange to ''= 0'', factorise, and keep the positive solution."],"answer":10,"tolerance":0}]}},{"n":13,"t":"assess_parts","p":"Dot patterns grow as shown: Pattern 1 has 1 dot, Pattern 2 has 4 dots, Pattern 3 has 9 dots and Pattern 4 has 16 dots.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Dot patterns grow as shown: Pattern 1 has 1 dot, Pattern 2 has 4 dots, Pattern 3 has 9 dots and Pattern 4 has 16 dots."}]},{"type":"assessDiagramBlock","attrs":{"spec":{"kind":"shape_pattern","title":"Dot patterns","patterns":[{"label":"Pattern 1","squares":0,"dots":1},{"label":"Pattern 2","squares":0,"dots":4},{"label":"Pattern 3","squares":0,"dots":9},{"label":"Pattern 4","squares":0,"dots":16}]}}}]},"e":"The counts are square numbers: 1, 4, 9, 16, so Pattern 5 has 25 dots and the nth pattern has n² dots. Pattern 20 has 20² = 400 dots.\n\nHint for next time: Look at the counts 1, 4, 9, 16 and name the family they belong to.","m":2,"df":"easy","tp":"quadratic sequences","st":"square-number patterns","cfg":{"source":"assess-prep-myp5-formative","question_number":13,"myp_criterion":"B","next_time_hint":"Look at the counts 1, 4, 9, 16 and name the family they belong to.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many dots does Pattern 5 have?","kind":"numeric","points":1,"hints":["Look at the counts 1, 4, 9, 16 and name the family they belong to.","These are the squares of the pattern numbers."],"answer":25,"tolerance":0},{"id":"b","label":"(b)","prompt":"How many dots does Pattern 20 have?","kind":"numeric","points":1,"hints":["An explicit rule beats drawing twenty patterns.","Square the pattern number."],"answer":400,"tolerance":0}]}},{"n":14,"t":"assess_parts","p":"A geometric sequence begins 3, 6, 12, 24, …","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A geometric sequence begins 3, 6, 12, 24, …"}]}]},"e":"Each term is double the previous one, so r = 2. a₈ = 3 × 2⁷ = 3 × 128 = 384.\n\nHint for next time: In a geometric sequence, neighbouring terms are linked by multiplication.","m":2,"df":"easy","tp":"geometric sequences","st":"common ratio and nth term","cfg":{"source":"assess-prep-myp5-formative","question_number":14,"myp_criterion":"A","next_time_hint":"In a geometric sequence, neighbouring terms are linked by multiplication.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"What is the common ratio?","kind":"numeric","points":1,"hints":["In a geometric sequence, neighbouring terms are linked by multiplication.","Divide any term by the term before it."],"answer":2,"tolerance":0},{"id":"b","label":"(b)","prompt":"Find the 8th term.","kind":"numeric","points":1,"hints":["Count how many multiplications take you from the 1st term to the 8th.","Use first term × ratio^(n − 1)."],"answer":384,"tolerance":0}]}},{"n":15,"t":"assess_parts","p":"A geometric sequence has first term 5 and common ratio 3.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A geometric sequence has first term 5 and common ratio 3."}]}]},"e":"aₙ = 5 × 3ⁿ⁻¹. a₆ = 5 × 3⁵ = 5 × 243 = 1215.\n\nHint for next time: A geometric explicit formula is ''first term × ratio^(n − 1)''.","m":2,"df":"medium","tp":"geometric sequences","st":"explicit formula for a geometric sequence","cfg":{"source":"assess-prep-myp5-formative","question_number":15,"myp_criterion":"B","next_time_hint":"A geometric explicit formula is ''first term × ratio^(n − 1)''.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Write the explicit formula. Type it like 5*3^(n-1).","kind":"expression","points":1,"hints":["A geometric explicit formula is ''first term × ratio^(n − 1)''.","Substitute a = 5 and r = 3 into that structure."],"accepted":["5*3^(n-1)","5×3^(n-1)","a_n=5*3^(n-1)","5(3)^(n-1)","5*3^(n−1)"]},{"id":"b","label":"(b)","prompt":"Find the 6th term.","kind":"numeric","points":1,"hints":["The exponent is one less than the term number.","Multiply 5 by 3 raised to the power 5."],"answer":1215,"tolerance":0}]}},{"n":16,"t":"assess_parts","p":"A ball''s bounce heights form the geometric sequence 80, 40, 20, 10, … centimetres.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A ball''s bounce heights form the geometric sequence 80, 40, 20, 10, … centimetres."}]}]},"e":"r = 40 ÷ 80 = 1/2. a₇ = 80 × (1/2)⁶ = 80 ÷ 64 = 1.25 cm.\n\nHint for next time: Divide a term by the one before it.","m":2,"df":"medium","tp":"geometric sequences","st":"decreasing geometric sequences","cfg":{"source":"assess-prep-myp5-formative","question_number":16,"myp_criterion":"A","next_time_hint":"Divide a term by the one before it.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"What is the common ratio? Type it as a fraction or a decimal.","kind":"text","points":1,"hints":["Divide a term by the one before it.","Compare 40 with 80."],"accepted":["1/2","0.5","½"]},{"id":"b","label":"(b)","prompt":"Find the height of the 7th bounce.","kind":"numeric","points":1,"hints":["Six multiplications by the ratio take you from the 1st to the 7th term.","Multiply 80 by the ratio raised to the power 6."],"answer":1.25,"tolerance":0.01,"unit":"cm"}]}},{"n":17,"t":"assess_parts","p":"In a geometric sequence, the 3rd term is 24 and the 6th term is 192.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In a geometric sequence, the 3rd term is 24 and the 6th term is 192."}]}]},"e":"From term 3 to term 6 is 3 multiplications by r, and 192 ÷ 24 = 8 = r³, so r = 2. Then a = 24 ÷ r² = 24 ÷ 4 = 6. Check: 6, 12, 24, 48, 96, 192.\n\nHint for next time: Count the multiplications between the two given terms.","m":2,"df":"hard","tp":"geometric sequences","st":"finding r and a from two terms","cfg":{"source":"assess-prep-myp5-formative","question_number":17,"myp_criterion":"B","next_time_hint":"Count the multiplications between the two given terms.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the common ratio.","kind":"numeric","points":1,"hints":["Count the multiplications between the two given terms.","Divide the later term by the earlier one, then take the cube root."],"answer":2,"tolerance":0},{"id":"b","label":"(b)","prompt":"Find the first term.","kind":"numeric","points":1,"hints":["Work backwards from a known term, undoing the ratio.","From the 3rd term, divide by the ratio twice."],"answer":6,"tolerance":0}]}},{"n":18,"t":"assess_parts","p":"Consider the arithmetic series 2 + 5 + 8 + … with 20 terms.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Consider the arithmetic series 2 + 5 + 8 + … with 20 terms."}]}]},"e":"Last term = 2 + 19 × 3 = 59. Sum = 20/2 × (2 + 59) = 10 × 61 = 610.\n\nHint for next time: A series question often needs the last term before it can be summed.","m":2,"df":"easy","tp":"arithmetic series","st":"sum of an arithmetic series","cfg":{"source":"assess-prep-myp5-formative","question_number":18,"myp_criterion":"A","next_time_hint":"A series question often needs the last term before it can be summed.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the 20th term.","kind":"numeric","points":1,"hints":["A series question often needs the last term before it can be summed.","Use first term + (n − 1) × difference."],"answer":59,"tolerance":0},{"id":"b","label":"(b)","prompt":"Find the sum of the first 20 terms.","kind":"numeric","points":1,"hints":["Pair the first and last terms — every pair has the same total.","Use S = n/2 × (first + last)."],"answer":610,"tolerance":0}]}},{"n":19,"t":"assess_parts","p":"A theatre has 15 rows of seats. The first row has 20 seats and each row behind it has 4 more seats than the row in front.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A theatre has 15 rows of seats. The first row has 20 seats and each row behind it has 4 more seats than the row in front."}]}]},"e":"Last row = 20 + 14 × 4 = 76 seats. Total = 15/2 × (20 + 76) = 7.5 × 96 = 720 seats.\n\nHint for next time: The rows form an arithmetic sequence.","m":2,"df":"medium","tp":"arithmetic series","st":"arithmetic series in real life","cfg":{"source":"assess-prep-myp5-formative","question_number":19,"myp_criterion":"D","next_time_hint":"The rows form an arithmetic sequence.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"How many seats are in the last (15th) row?","kind":"numeric","points":1,"hints":["The rows form an arithmetic sequence.","Use first row + (15 − 1) × the row-to-row increase."],"answer":76,"tolerance":0},{"id":"b","label":"(b)","prompt":"How many seats does the theatre have in total?","kind":"numeric","points":1,"hints":["Add the sequence up with the pairing idea, not row by row.","Use S = n/2 × (first row + last row)."],"answer":720,"tolerance":0}]}},{"n":20,"t":"numeric","p":"Find the sum of the first 8 terms of the geometric series 3 + 6 + 12 + …","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Find the sum of the first 8 terms of the geometric series 3 + 6 + 12 + …"}]}]},"e":"a = 3, r = 2. S₈ = 3 × (2⁸ − 1)/(2 − 1) = 3 × 255 = 765.\n\nHint for next time: Name a and r first, then choose the sum formula.","m":2,"df":"easy","tp":"geometric series","st":"sum of a geometric series","cfg":{"source":"assess-prep-myp5-formative","question_number":20,"myp_criterion":"A","next_time_hint":"Name a and r first, then choose the sum formula.","assessment_style":"assess_prep_typed","hints":["Identify the first term and the ratio before summing anything.","Use S = a(rⁿ − 1)/(r − 1) with n = 8."],"numeric_answer":765,"tolerance":0}},{"n":21,"t":"numeric","p":"Find the sum of the first 6 terms of the geometric series 16 + 8 + 4 + … Give your answer as a decimal.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Find the sum of the first 6 terms of the geometric series 16 + 8 + 4 + … Give your answer as a decimal."}]}]},"e":"a = 16, r = 1/2. S₆ = 16 × (1 − (1/2)⁶)/(1 − 1/2) = 16 + 8 + 4 + 2 + 1 + 0.5 = 31.5.\n\nHint for next time: The ratio is less than 1 here — check whether the formula form you use matches that.","m":2,"df":"medium","tp":"geometric series","st":"geometric series with ratio below 1","cfg":{"source":"assess-prep-myp5-formative","question_number":21,"myp_criterion":"A","next_time_hint":"The ratio is less than 1 here — check whether the formula form you use matches that.","assessment_style":"assess_prep_typed","hints":["The ratio is less than 1 here — check whether the formula form you use matches that.","Either add the six terms directly or use S = a(1 − rⁿ)/(1 − r)."],"numeric_answer":31.5,"tolerance":0.01}},{"n":22,"t":"assess_parts","p":"A savings plan pays in $10 in week 1 and doubles the payment every week: $10, $20, $40, …","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A savings plan pays in "},{"type":"text","text":"$10 in week 1 and doubles the payment every week: $"},{"type":"text","text":"10, "},{"type":"text","text":"$20, $"},{"type":"text","text":"40, …"}]}]},"e":"This is geometric with a = 10, r = 2. Week 6 payment = 10 × 2⁵ = $320. Total over 6 weeks = 10 × (2⁶ − 1)/(2 − 1) = 10 × 63 = $630.\n\nHint for next time: Each week multiplies the payment — count the doublings since week 1.","m":2,"df":"medium","tp":"geometric series","st":"geometric series in real life","cfg":{"source":"assess-prep-myp5-formative","question_number":22,"myp_criterion":"D","next_time_hint":"Each week multiplies the payment — count the doublings since week 1.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"What is the payment in week 6?","kind":"numeric","points":1,"hints":["Each week multiplies the payment — count the doublings since week 1.","Use first payment × ratio^(n − 1)."],"answer":320,"tolerance":0,"unit":"$"},{"id":"b","label":"(b)","prompt":"What is the total paid over the first 6 weeks?","kind":"numeric","points":1,"hints":["A total of payments is a series, not a single term.","Sum the geometric series with a = 10, r = 2, n = 6."],"answer":630,"tolerance":0,"unit":"$"}]}},{"n":23,"t":"numeric","p":"For the series 1 + 2 + 4 + 8 + …, the sum of the first n terms is 1023. Find n.","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For the series 1 + 2 + 4 + 8 + …, the sum of the first n terms is 1023. Find n."}]}]},"e":"Sₙ = (2ⁿ − 1)/(2 − 1) = 2ⁿ − 1. Setting 2ⁿ − 1 = 1023 gives 2ⁿ = 1024 = 2¹⁰, so n = 10.\n\nHint for next time: Let the sum formula equal the target and solve for n.","m":2,"df":"hard","tp":"geometric series","st":"finding the number of terms","cfg":{"source":"assess-prep-myp5-formative","question_number":23,"myp_criterion":"B","next_time_hint":"Let the sum formula equal the target and solve for n.","assessment_style":"assess_prep_typed","hints":["Write the sum formula with n still unknown, then solve.","Set a(rⁿ − 1)/(r − 1) equal to 1023 and recognise the power of 2."],"numeric_answer":10,"tolerance":0}},{"n":24,"t":"assess_parts","p":"Sequence A is arithmetic: 4, 7, 10, 13, … Sequence B is geometric: 2, 6, 18, 54, …","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sequence A is arithmetic: 4, 7, 10, 13, … Sequence B is geometric: 2, 6, 18, 54, …"}]}]},"e":"A: aₙ = 3n + 1, so a₁₀ = 31. B: bₙ = 2 × 3ⁿ⁻¹, so b₅ = 162. B grows by multiplying, so it passes 100 first, at its 5th term (162), while A only reaches 103 at term 34.\n\nHint for next time: Treat A on its own first: what is added each time?","m":3,"df":"hard","tp":"mixed challenge","st":"comparing growth of two sequences (integrated challenge)","cfg":{"source":"assess-prep-myp5-formative","question_number":24,"myp_criterion":"D","next_time_hint":"Treat A on its own first: what is added each time?","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the 10th term of Sequence A.","kind":"numeric","points":1,"hints":["Treat A on its own first: what is added each time?","Use first term + (n − 1) × difference."],"answer":31,"tolerance":0},{"id":"b","label":"(b)","prompt":"Find the 5th term of Sequence B.","kind":"numeric","points":1,"hints":["Treat B on its own: what is multiplied each time?","Use first term × ratio^(n − 1)."],"answer":162,"tolerance":0},{"id":"c","label":"(c)","prompt":"Which sequence''s terms first exceed 100? Type: A or B.","kind":"text","points":1,"hints":["Compare how the two growth patterns behave over many terms.","Multiplying by 3 grows far faster than adding 3 — check B''s early terms."],"accepted":["B","Sequence B"]}]}},{"n":25,"t":"assess_parts","p":"A pattern of triangle numbers begins 1, 3, 6, 10, 15, … (each term adds one more than the previous increase).","d":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A pattern of triangle numbers begins 1, 3, 6, 10, 15, … (each term adds one more than the previous increase)."}]}]},"e":"First differences 2, 3, 4, 5 increase by 1, so the next difference is 6 and the next term is 21. The second difference is 1, giving an n² coefficient of 1/2; subtracting n²/2 leaves the pattern (n² + n)/2, so aₙ = (n² + n)/2. Check: n = 4 gives 10.\n\nHint for next time: Look at how the gaps themselves are growing.","m":2,"df":"hard","tp":"mixed challenge","st":"investigating a non-standard pattern (integrated challenge)","cfg":{"source":"assess-prep-myp5-formative","question_number":25,"myp_criterion":"B","next_time_hint":"Look at how the gaps themselves are growing.","assessment_style":"assess_prep_typed","hints":[],"parts":[{"id":"a","label":"(a)","prompt":"Find the next term.","kind":"numeric","points":1,"hints":["Look at how the gaps themselves are growing.","Extend the first differences by their own pattern, then add on."],"answer":21,"tolerance":0},{"id":"b","label":"(b)","prompt":"Write the nth-term formula. Type it like (n^2+n)/2.","kind":"expression","points":1,"hints":["The second difference tells you the n² coefficient — it is not a whole number here.","Halve the second difference for the n² coefficient, subtract that part, and find what remains."],"accepted":["(n^2+n)/2","(n²+n)/2","a_n=(n^2+n)/2","n(n+1)/2","(n(n+1))/2","0.5n^2+0.5n"]}]}}]'::jsonb) as x
on conflict (id) do nothing;

insert into question_options (id, question_id, label, is_correct, position)
select ('b5000000-0000-4000-8000' || lpad((300000 + (q.config->>'question_number')::int * 100 + (v.idx - 1))::text, 12, '0'))::uuid,
       q.id, v.variant, true, v.idx::int
  from questions q
  cross join lateral jsonb_array_elements_text(q.config->'accepted') with ordinality as v(variant, idx)
 where q.organization_id = '0a400000-0000-4000-8000-000000000001' and q.config->>'source' = 'assess-prep-myp5-formative'
on conflict (id) do nothing;

insert into quiz_questions (quiz_id, question_id, position, points)
select 'b5000000-0000-4000-8000-000000000001', q.id, (q.config->>'question_number')::int, q.points
  from questions q
 where q.organization_id = '0a400000-0000-4000-8000-000000000001' and q.config->>'source' = 'assess-prep-myp5-formative'
on conflict (quiz_id, question_id) do nothing;

insert into exams (id, organization_id, quiz_id, class_id, title, description, instructions, duration_minutes, status, access_code, shared_link_enabled, settings, created_by)
values ('b5000000-0000-4000-8000-000000000002', '0a400000-0000-4000-8000-000000000001', 'b5000000-0000-4000-8000-000000000001', '0a400000-0000-4000-8000-000000000110', 'MYP 5 Mathematics — Formative Assessment: Sequences and Series', 'Grade 10 · MYP 5 · Mathematics · Formative (Assess Prep). Explicit and recursive formulae, arithmetic, quadratic and geometric sequences, arithmetic and geometric series. Type every answer — there are no options to choose from.',
  'Type every answer in the box provided — there are no options to choose from. Multi-part questions have a separate box and separate marks for each part. Press the Hint button whenever you are stuck: hints show you the way but never give the answer, and using a hint costs no marks. You have 45 minutes. Your feedback shows the correct answer, a worked solution and a hint for next time for every question.',
  45, 'open', 'MYP5-SEQUENCES-2026', true,
  '{"proctoring":false,"require_screen_share":false,"randomize_questions":false,"randomize_options":false,"pass_mark_percent":50,"results_published":true,"access_mode":"shared_link","identity_fields":[],"eligible_class_ids":["0a400000-0000-4000-8000-000000000110"],"attempt_policy":"single_resume","assessment_kind":"formative","grade_level":"10","curriculum":"MYP 5","subject":"Mathematics","total_marks":50,"source":"assess-prep-myp5-formative"}'::jsonb, '3c3ed712-f409-4aa1-a645-816418e22ec4')
on conflict (id) do nothing;

insert into question_hints (id, organization_id, exam_id, question_id, level, body, status, source, created_by, approved_by)
select ('b5000000-0000-4000-8000' || lpad((500000 + (q.config->>'question_number')::int * 10 + h.level)::text, 12, '0'))::uuid,
       '0a400000-0000-4000-8000-000000000001', 'b5000000-0000-4000-8000-000000000002', q.id, h.level, h.body, 'published', 'manual', '3c3ed712-f409-4aa1-a645-816418e22ec4', '3c3ed712-f409-4aa1-a645-816418e22ec4'
  from questions q
  cross join lateral (values
    (1, case when q.type = 'assess_parts'
             then 'Work through the parts in order: later parts often build on earlier ones. Every part also has its own Hint button beside its answer box.'
             else q.config->'hints'->>0 end),
    (2, case when q.type = 'assess_parts'
             then 'For part (a), start here: ' || (q.config->'parts'->0->'hints'->>0)
             else q.config->'hints'->>1 end)
  ) as h(level, body)
 where q.organization_id = '0a400000-0000-4000-8000-000000000001' and q.config->>'source' = 'assess-prep-myp5-formative'
on conflict (id) do nothing;

